function clone(x) {
	return JSON.parse(JSON.stringify(x));
}
var clamp = (v, a, b) => Math.max(a, Math.min(b, v));
var rnd = Math.random;
var pick = (arr) => arr[Math.floor(rnd() * arr.length)];
function mulberry32(seed) {
	let a = seed >>> 0;
	return function() {
		a |= 0;
		a = a + 1831565813 | 0;
		let t = Math.imul(a ^ a >>> 15, 1 | a);
		t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
		return ((t ^ t >>> 14) >>> 0) / 4294967296;
	};
}
function fmtLap(s) {
	if (s == null || !isFinite(s)) return "—";
	const m = Math.floor(s / 60);
	const sec = s - m * 60;
	return `${m}:${sec < 10 ? "0" : ""}${sec.toFixed(3)}`;
}
function fmtGap(s) {
	if (!isFinite(s)) return "—";
	return `+${s.toFixed(3)}`;
}
function money(n) {
	const abs = Math.abs(n);
	if (abs >= 1e6) return `${n < 0 ? "-" : ""}$${(abs / 1e6).toFixed(1)}M`;
	if (abs >= 1e3) return `${n < 0 ? "-" : ""}$${(abs / 1e3).toFixed(0)}K`;
	return `$${Math.round(n)}`;
}
function supplierPower(gs, t) {
	if (t.works) return t.power;
	const sup = Object.values(gs.teams).find((x) => x.seriesId === t.seriesId && x.works && x.engineMaker === t.engineMaker);
	return sup ? sup.power * .97 : t.power * .95;
}
function carPerf(gs, t, c) {
	const aeroW = .6 + .8 * (c.aeroSens || .5);
	const powW = .6 + .8 * (c.powerSens || .5);
	const pwr = supplierPower(gs, t);
	const wearPen = Math.max(0, (t.wear || 0) - 55) * .09;
	const v = t.base * .46 + (t.aero || 60) * .24 * aeroW + (t.chassis || 60) * .24 + pwr * .25 * powW - wearPen;
	return isFinite(v) ? clamp(v, 20, 100) : 50;
}
function driverSkill(d, mode, wet) {
	const w = mode === "quali" ? {
		p: .55,
		r: .15,
		c: .2,
		w: wet ? .25 : .05,
		f: .05
	} : {
		p: .4,
		r: .25,
		c: .25,
		w: wet ? .3 : .05,
		f: .05
	};
	const wetSkill = wet ? d.wet : d.wet * .25;
	return clamp(d.pace * w.p + d.racecraft * w.r + d.consistency * w.c + wetSkill * w.w + d.form * w.f * 2, 15, 100);
}
function baseLap(c, s) {
	let base = c.kind === "oval" ? c.lenKm * 14.5 + 6 : c.kind === "street" ? c.lenKm * 15.6 + 16 : c.lenKm * 14.8 + 14;
	if (s === "f2") base += 4.6;
	if (s === "f3") base += 8.2;
	if (s === "fe") base += 6.4;
	return base;
}
function compoundDef(s, id) {
	return SERIES_META[s].compounds.find((c) => c.id === id) ?? SERIES_META[s].compounds[0];
}
function tireName(sid, id) {
	return compoundDef(sid, id).name;
}
function dryCompounds(sid) {
	return SERIES_META[sid].compounds.filter((c) => !["I", "W"].includes(c.id));
}
/** Расход топлива за круг в зависимости от режима (кг/круг). Единый источник правды. */
function fuelBurnFor(fuelMode) {
	return fuelMode === "eco" ? 1.05 : fuelMode === "push" ? 1.42 : 1.25;
}
/** Состав по умолчанию для старта (средний). */
function defaultStartTire(sid) {
	const dry = dryCompounds(sid);
	return dry[Math.floor(dry.length / 2)]?.id ?? "M";
}
/** «Работа с шинами» команды: множитель деградации (90 → 0.80, 50 → 1.0, 30 → 1.10) */
function tireCareFactor(gs, teamId) {
	const t = gs.teams[teamId];
	if (!t) return 1;
	return 1.25 - (t.tires ?? 70) / 200;
}
function defaultSetup() {
	return {
		aero: 50,
		mech: 50,
		tires: 50,
		brake: 50,
		diff: 50
	};
}
